import re, gzip, zlib, json, sys, os

PATH = '/Users/oyamahappa/Documents/Agent/DSH/2026_11_01__14_13_40'
d = open(PATH, 'rb').read()

REQ_RE = re.compile(rb'(?:GET|POST|PUT|DELETE|HEAD|PATCH) /[^\x00\r\n]*? HTTP/1\.[01]')
RESP_RE = re.compile(rb'HTTP/1\.[01] \d{3}')

def parse_head(buf):
    lines = buf.split(b'\r\n')
    first = lines[0].decode('latin1')
    hdrs = []
    for ln in lines[1:]:
        if not ln.strip():
            break
        if b':' in ln:
            k, v = ln.split(b':', 1)
            hdrs.append((k.decode('latin1').strip(), v.decode('latin1').strip()))
    return first, hdrs

def hget(hdrs, name):
    for k, v in hdrs:
        if k.lower() == name.lower():
            return v
    return None

def decode_body(body, hdrs):
    enc = (hget(hdrs, 'content-encoding') or '').lower()
    out = body
    try:
        if 'br' in enc:
            try:
                import brotli
                out = brotli.decompress(body)
            except Exception:
                out = body
        elif 'gzip' in enc:
            out = gzip.decompress(body)
        elif 'deflate' in enc:
            out = zlib.decompress(body, -15)
    except Exception:
        out = body
    return out, enc

reqs = [m.start() for m in REQ_RE.finditer(d)]
resps = [m.start() for m in RESP_RE.finditer(d)]

records = []
for idx, rq in enumerate(reqs):
    he = d.find(b'\r\n\r\n', rq)
    reqline, reqh = parse_head(d[rq:he+2])
    cl = hget(reqh, 'content-length')
    rq_body_len = int(cl) if cl and cl.isdigit() else 0
    rq_body = d[he+4:he+4+rq_body_len]
    # response following
    nxt = [r for r in resps if r > he+4+rq_body_len]
    if not nxt:
        break
    rs = nxt[0]
    rhe = d.find(b'\r\n\r\n', rs)
    status, rsh = parse_head(d[rs:rhe+2])
    rcl = hget(rsh, 'content-length')
    te = (hget(rsh, 'transfer-encoding') or '').lower()
    if rcl and rcl.isdigit():
        rs_body = d[rhe+4:rhe+4+int(rcl)]
    elif 'chunked' in te:
        rs_body = d[rhe+4:nxt[1] if len(nxt) > 1 else len(d)]
    else:
        stop = next((r for r in resps if r > rhe+4), None)
        rs_body = d[rhe+4:stop] if stop else b''
    dec, enc = decode_body(rs_body, rsh)
    records.append(dict(i=idx, reqline=reqline, reqh=reqh, rq_body=rq_body, status=status,
                        rsh=rsh, rs_body=rs_body, rs_dec=dec, enc=enc, offset=rq))

os.makedirs('/Users/oyamahappa/Documents/Agent/DSH/.work/cap2026', exist_ok=True)
with open('/Users/oyamahappa/Documents/Agent/DSH/.work/cap2026/records.json', 'w') as f:
