for m in TYPE_RE.finditer(d):
    tp = m.start()
    ln = int.from_bytes(d[tp-2:tp], 'big')
    frames.append(dict(off=tp, type=d[tp], id=d[tp+4], payload=d[tp+5:tp+5+ln]))

reqs = {}
resps = {}
for f in frames:
    t, fid, p = f['type'], f['id'], f['payload']
    if t == 3 and re.match(rb'(GET|POST|PUT|DELETE|HEAD|PATCH) /', p):
        reqs.setdefault(fid, {})['head'] = p
    elif t == 4 and fid in reqs:
        reqs[fid].setdefault('body', b''); reqs[fid]['body'] += p
    elif t == 6 and p.startswith(b'HTTP/1.1'):
        resps.setdefault(fid, {})['head'] = p
    elif t == 7 and fid in resps:
        resps[fid].setdefault('body', b''); resps[fid]['body'] += p

def hget(head, name):
    for ln in head.split(b'\r\n')[1:]:
        if ln.lower().startswith(name.lower().encode() + b':'):
            return ln.split(b':', 1)[1].strip().decode('latin1')
    return None

def decode(body, head):
    enc = (hget(head, 'content-encoding') or '').lower()
    try:
        if 'br' in enc:
            import brotli; return brotli.decompress(body)
        if 'gzip' in enc: return gzip.decompress(body)
        if 'deflate' in enc: return zlib.decompress(body, -15)
    except Exception as e:
        return body
    return body

summary = []
for fid in sorted(reqs):
    rq = reqs[fid]; rs = resps.get(fid, {})
    rq_head = rq.get('head', b''); rq_body = rq.get('body', b'')
    rs_head = rs.get('head', b''); rs_body = rs.get('body', b'')
    rs_dec = decode(rs_body, rs_head) if rs_body else b''
    name = '%02d' % fid
    open(os.path.join(OUT, name + '_req.txt'), 'wb').write(rq_head + b'\r\n\r\n' + rq_body)
