import gzip
import json
import os
import shlex
import sys
import urllib.parse

CAP = '/Users/oyamahappa/Documents/Agent/DSH/2026_11_01__14_13_40'
TXN = '/Users/oyamahappa/Documents/Agent/DSH/.work/cap2026/txn'


def load(n):
    raw = open(os.path.join(TXN, '%02d_req.txt' % n), 'rb').read()
    head, _, rest = raw.partition(b'\r\n\r\n')
    body = rest[4:] if rest.startswith(b'\r\n\r\n') else rest
    rh = b''
    p = os.path.join(TXN, '%02d_resp_head.txt' % n)
    if os.path.exists(p):
        rh = open(p, 'rb').read()
    return head.decode('latin1'), body, rh.decode('latin1')


def parse(head):
    lines = head.split('\r\n')
    method, target, _ = lines[0].split(' ')
    hdrs = []
    for ln in lines[1:]:
        if ':' in ln:
            k, v = ln.split(':', 1)
            hdrs.append([k.strip(), v.strip()])
    return method, target, hdrs


def build(n, sets, dels, params, drop_cookie):
    head, body, rh = load(n)
    method, target, hdrs = parse(head)
    if params:
        u = urllib.parse.urlsplit(target)
        q = dict(urllib.parse.parse_qsl(u.query, keep_blank_values=True))
        for k, v in params:
            q[k] = v
        target = urllib.parse.urlunsplit((u.scheme, u.netloc, u.path, urllib.parse.urlencode(q), u.fragment))
    out = []
    seen = set()
    for k, v in hdrs:
        lk = k.lower()
        if drop_cookie and lk == 'cookie':
            continue
        if lk in dict((d.lower(), 1) for d in dels):
            continue
        val = v
        for sk, sv in sets:
            if lk == sk.lower():
                val = sv
        out.append([k, val])
        seen.add(lk)
    for sk, sv in sets:
        if sk.lower() not in seen:
            out.append([sk, sv])
    return method, target, out, body, rh


def to_curl(method, target, hdrs, body):
    host = dict((k.lower(), v) for k, v in hdrs).get('host', '')
    url = target if target.startswith('http') else 'https://%s%s' % (host, target)
    parts = ['curl', '-sS', '-X', method, shlex.quote(url)]
    for k, v in hdrs:
        if k.lower() == 'host':
            continue
        parts += ['-H', shlex.quote('%s: %s' % (k, v))]
    if body:
        p = '/Users/oyamahappa/Documents/Agent/DSH/.work/cap2026/body_%d.bin' % abs(hash(url) % 10000)
        open(p, 'wb').write(body)
        parts += ['--data-binary', '@' + p]
    return ' '.join(parts)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('cmd', choices=['list', 'show', 'curl'])
    ap.add_argument('n', nargs='?', type=int)
    ap.add_argument('--set', action='append', default=[], metavar='K=V')
    ap.add_argument('--del', action='append', default=[], dest='dels', metavar='K')
    ap.add_argument('--param', action='append', default=[], metavar='K=V')
    ap.add_argument('--drop-cookie', action='store_true')
    a = ap.parse_args()

    if a.cmd == 'list':
        idx = json.load(open('/Users/oyamahappa/Documents/Agent/DSH/.work/cap2026/index.json'))
        for r in idx:
            print('%02d %-95s | %s' % (r['id'], r['req'][:95], r['status']))
        return

    if a.n is None:
        sys.exit('need transaction id')

    kv = lambda xs: [tuple(x.split('=', 1)) for x in xs]
    method, target, hdrs, body, rh = build(a.n, kv(a.set), a.dels, kv(a.param), a.drop_cookie)

    if a.cmd == 'show':
        print('%s %s' % (method, target))
        for k, v in hdrs:
            print('%s: %s' % (k, v))
        print('--- body %d bytes' % len(body))
        print(rh.split('\r\n')[0] if rh else '(no response captured)')
        return

    print(to_curl(method, target, hdrs, body))


if __name__ == '__main__':
    main()
